/**
 * The clip in the "What's new" popup, embedded as a data URI. Terminus makes
 * no network requests of its own, so the popup can't point at a URL (see
 * gettingStarted.ts); a short WebM is also a fraction of the size of the
 * GIF in the README.
 *
 * Regenerate from screenshots/multi-agent-demo.gif with:
 *   ffmpeg -i screenshots/multi-agent-demo.gif -vf "fps=10,scale=900:-2:flags=lanczos,format=yuv420p" \
 *     -c:v libvpx-vp9 -b:v 0 -crf 32 -an -row-mt 1 whatsnew.webm
 * then base64 the file into the constant below.
 */
export const WHATS_NEW_VIDEO = "data:video/webm;base64,";
